Add-Type -AssemblyName System.Windows.Forms; Add-Type -AssemblyName System.Drawing; $form = New-Object System.Windows.Forms.Form; $form.FormBorderStyle = 'None'; $form.WindowState = 'Maximized'; $form.TopMost = $true; $form.BackColor = 'DarkRed'; $form.Opacity = 0.5; $form.ShowInTaskbar = $false; $form.Cursor = 'None'; $label = New-Object System.Windows.Forms.Label; $label.Text = 'Let me free.'; $label.TextAlign = 'MiddleCenter'; $label.Font = New-Object System.Drawing.Font('Ink Free', 32, [System.Drawing.FontStyle]::Regular); $label.ForeColor = 'Red'; $label.BackColor = 'Transparent'; $label.AutoSize = $true; $form.Controls.Add($label); $form.Show(); $player = New-Object System.Media.SoundPlayer('C:\Windows\Media\Windows Information Bar.wav'); $centerX = ($form.Width - $label.Width) / 2; $centerY = ($form.Height - $label.Height) / 2; $shakeTimer = New-Object System.Windows.Forms.Timer; $shakeTimer.Interval = 50; $random = New-Object System.Random; $shakeTimer.Add_Tick({;   $shakeX = $random.Next(-40, 41);   $shakeY = $random.Next(-40, 41);   $label.Location = New-Object System.Drawing.Point(($centerX + $shakeX), ($centerY + $shakeY));   $player.Play(); }); $shakeTimer.Start(); $timer = New-Object System.Windows.Forms.Timer; $timer.Interval = 5000; $timer.Add_Tick({$form.Close(); $timer.Stop()}); $timer.Start(); while($form.Visible){[System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 50}